// Social affinity is independent of professional compatibility. Reads never mutate saves.
const hash=text=>{let n=2166136261;for(const c of String(text)){n^=c.charCodeAt(0);n=Math.imul(n,16777619);}return n>>>0;};
const clamp=n=>Math.max(0,Math.min(100,n));
export const LEVELS=['매우 나쁨','나쁨','보통','좋음','매우 좋음'];
export const level=value=>LEVELS[Math.min(4,Math.floor(clamp(value)/20))];
export const key=(a,b)=>[a,b].sort().join('|');
export function initRelations(s){s.relationSeed??=s.seed;s.relationStart??=s.month;s.relations??={};s.relationLog??=[];}
const caches=new WeakMap();
export function affinity(s,a,b){if(!s||!a||!b)return 50;if(a===b)return 100;const k=key(a,b),stamp=`${s.month}/${s.relationRevision??0}`;let cache=caches.get(s);if(!cache||cache.stamp!==stamp){cache={stamp,values:new Map()};caches.set(s,cache);}if(cache.values.has(k))return cache.values.get(k);const seed=s.relationSeed??s.seed,record=s.relations?.[k];let value=record?.value??(10+hash(seed+k)%81);for(let month=(record?.month??s.relationStart??s.month)+1;month<=s.month;month++){const roll=hash(seed+k+':'+month);if(roll%100<22)value=clamp(value+(roll%2?1:-1)*(1+Math.floor(roll/100)%3));}cache.values.set(k,value);return value;}
export function adjust(s,a,b,delta,reason){if(!a||!b||a===b)return;initRelations(s);const before=affinity(s,a,b),value=clamp(before+delta);s.relations[key(a,b)]={value,month:s.month};s.relationRevision=(s.relationRevision??0)+1;if(value!==before){s.relationLog.unshift({month:s.month,a,b,before,value,reason});s.relationLog=s.relationLog.slice(0,120);}}
export function teamAffinity(s,ids){ids=[...new Set(ids.filter(Boolean))];let total=0,count=0;for(let i=0;i<ids.length;i++)for(let j=i+1;j<ids.length;j++){total+=affinity(s,ids[i],ids[j]);count++;}return count?Math.round(total/count):50;}
export function relationshipFactor(s,p,team=[],company='c0'){const peers=team.filter(id=>id&&id!==p.id);const social=peers.length?peers.reduce((n,id)=>n+affinity(s,p.id,id),0)/peers.length:50;return Math.round((1+(50-affinity(s,p.id,company))*.002+(50-social)*.001)*100)/100;}
export function productionBonds(s,f,delta,reason){const ids=[f.script.writer,f.director,...f.leads,...f.supports,...(f.cameos??[])];for(const id of ids)adjust(s,id,f.company,delta,reason);for(let i=0;i<ids.length;i++)for(let j=i+1;j<ids.length;j++)adjust(s,ids[i],ids[j],delta,reason);}
export const AGENCIES=Object.entries({magazine:['스크린월간','시네마저널','필름포커스','장면과사람','무비아카이브','은막리뷰','프레임매거진','영화의온도','컷앤스토리','필름스펙트럼'],press:['문화데일리','무비프레스','스크린투데이','아트뉴스룸','영화현장신문','시네마리포트','컬처브리핑','렌즈타임즈','필름인사이트','무비와이어'],youtube:['무비살롱','한컷채널','시네마연구소','영화수다방','프레임톡','팝콘스튜디오','무비레터TV','씬메이커','스크린산책','영화뒤편'],tv:['한빛방송','다온TV','누리문화방송','온스크린TV','별빛방송','새봄네트워크','아트웨이TV','열린무대방송','무비플러스방송','문화온에어'],goods:['프레임팩토리','씬굿즈','무비크래프트','별빛제작소','스크린메이드','이야기공방','필름오브제','장면상점','아트픽셀굿즈','엔딩컬렉션']}).flatMap(([channel,names])=>names.map((name,i)=>({id:`agency-${channel}-${i}`,name,channel,reach:Math.round((.85+i*.035)*100)/100,cost:Math.round((.8+i*.045)*100)/100})));
export function mediaTerms(s,f,agency,baseCost){const company=affinity(s,agency.id,f.company),people=Math.round(f.leads.reduce((n,id)=>n+affinity(s,agency.id,id),0)/f.leads.length);return{company,people,cost:Math.round(baseCost*agency.cost*(1+(50-company)*.003)*100)/100,bonus:Math.round((company-50)/12+(people-50)/15+(agency.reach-1)*15)};}
